import re

def maskPII(s: str) -> str:
    if '@' in s:
        parts = s.split('@')
        name1 = parts[0].lower()
        masked_name1 = name1[0] + '*****' + name1[-1] if len(name1) > 2 else name1.lower()
        return f"{masked_name1}@{parts[1].lower()}"
    else:
        digits = re.sub(r'[^0-9]', '', s)
        if len(digits) == 10:
            return "***-***-" + digits[-4:]
        else:
            country_code = digits[:-10]
            local = digits[-10:]
            if len(country_code) == 1:
                return "+***-***-***-" + local[-4:]
            else:
                return "+" + '*' * (len(country_code) - 1) + "-***-***-" + local[-4:]
